def transform(grid):
    # Overlay four aligned 4x4 color masks; later palette priority wins.
    out=[]
    for r in range(4):
        row=[]
        for c in range(4):
            v=0
            for color,start in ((5,5),(8,0),(4,15),(9,10)):
                if grid[r][start+c] == color:
                    v=color
            row.append(v)
        out.append(row)
    return out
